def Target : Prop :=
  ∀ (X Y : Type), Nonempty X → ∀ (N : S1 X Y),
    ∃ N' : S1 X Y, N'.D11 ∧ N'.d13 = N.d13 + 1 ∧ S1.D6 N' N

